import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import assert from 'node:assert/strict';
import ts from 'typescript';
// Declarations are generated by tsc, so signatures cannot silently diverge from published types.
let output =
  '# Korea Map Kit core API reference\n\nGenerated from TypeScript declarations by `pnpm docs:api`. Do not edit by hand.\n\n[Usage, semantics and platform parity](../public-api.md)\n\n';
for (const file of readdirSync('packages/core/dist')
  .filter((name) => name.endsWith('.d.ts') && name !== 'index.d.ts')
  .sort()) {
  const content = readFileSync(`packages/core/dist/${file}`, 'utf8').replaceAll('\r\n', '\n');
  const source = ts.createSourceFile(file, content, ts.ScriptTarget.Latest, true);
  const declarations = source.statements.filter((node) =>
    node.modifiers?.some((modifier) => modifier.kind === ts.SyntaxKind.ExportKeyword),
  );
  for (const node of declarations) {
    const name = node.name?.getText(source);
    assert(name, `Unnamed export in ${file}`);
    output += `## ${name}\n\n\`\`\`ts\n${node.getFullText(source).trim()}\n\`\`\`\n\n`;
  }
}
output = output.trimEnd() + '\n';
const path = 'docs/api/core.md';
if (process.argv.includes('--check'))
  assert.equal(
    readFileSync(path, 'utf8'),
    output,
    'Generated API reference is stale; run pnpm docs:api',
  );
else writeFileSync(path, output);
console.log(`PASS: ${path} matches exported declarations`);
